# area: inheritance_mro
# hypothesis: In a diamond, cooperative super() calls follow the C3 MRO, so each class's describe runs exactly once and the result lists the classes in MRO order.
from typing import reveal_type


class Base:
    def describe(self) -> list[str]:
        return ['Base']


class Left(Base):
    def describe(self) -> list[str]:
        return ['Left', *super().describe()]


class Right(Base):
    def describe(self) -> list[str]:
        return ['Right', *super().describe()]


class Bottom(Left, Right):
    def describe(self) -> list[str]:
        return ['Bottom', *super().describe()]


print(Bottom.__mro__)
b = Bottom()
d = b.describe()
reveal_type(d)
print(d)
assert d == ['Bottom', 'Left', 'Right', 'Base']
